factors = {'전기(kWh)': 0.474, '버스(km)': 0.1, '소고기(kg)': 27, '채소(kg)': 0.5}
amounts = {'전기(kWh)': 6, '버스(km)': 12, '소고기(kg)': 0.15, '채소(kg)': 0.3}

result = {}
for a in factors:
    result[a] = amounts[a] * factors[a]

big = ''
for a in result:
    if big == '' or result[a] > result[big]:
        big = a

total = sum(result.values())
print(f'가장 큰 배출원: {big}')
print(f'지금 합계: {total:.2f}kg')
print(f'{big}을(를) 절반으로 줄이면: {total - result[big] / 2:.2f}kg')
